function escapeHtml(input) {
  return String(input).replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
}
const p = text => `<p>${escapeHtml(text)}</p>`;
const list = (items, ordered = false) => `<${ordered ? 'ol' : 'ul'}>${items.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</${ordered ? 'ol' : 'ul'}>`;
const header = title => `<h3>${escapeHtml(title)}</h3>`;
function formatSection(letter, html) {
  const text = html.replace(/<[^>]*>/g, ' ').replace(/&[^;]+;/g, ' ').replace(/\s+/g,' ').trim();
  const headings = { A: 'Interviewer questions', B: 'Deep technical explanation', C: 'Interview-ready spoken answer', D: 'Follow-up pressure test', E: 'Production scenario', F: 'Interview takeaways' };
  return { letter, heading: headings[letter], html, text };
}
export function createDeepSections(id) {
  const x = deepLessons[Number(id)];
  if (!x) return null;
  const steps = ['Requirements & situation', 'Competing hypotheses', 'Instrumentation', 'Diagnosis & implementation', 'Validation gates'];
  return [
    formatSection('A', `<p>Explain the mechanism and defend each design decision aloud before reading the model answer.</p>${list(x.questions,true)}`),
    formatSection('B', [
      header('1. Mechanism and data flow'), ...x.mechanism.map(p),
      header('2. Mathematics and assumptions'), ...x.equations.map(([math, why])=>`<div class="formula"><code>${escapeHtml(math)}</code>${p(why)}</div>`),
      header('3. Architecture and alternatives'), p(x.design),
      header('4. Implementation sketch'), `<pre class="foundation-pseudocode"><code>${escapeHtml(x.implementation)}</code></pre><p>This is explanatory pseudocode, not a runnable production implementation. Verify dimensions, masks and APIs for a specific framework.</p>`,
      header('5. Latency, memory, cost and measurement'), p(x.performance),
      header('6. Failure modes and debugging'), p(x.failures)
    ].join('')),
    formatSection('C', `<blockquote>${escapeHtml(x.spoken)}</blockquote><p>Use this as a structure, not as a script to memorize. Be ready to derive the equations and justify assumptions.</p>`),
    formatSection('D', `<p>A strong answer explains the mechanism, the alternative, its cost and what measurement would decide.</p>${x.pressure.map(([q,a])=>`<div class="foundation-probe"><h4>${escapeHtml(q)}</h4>${p(a)}</div>`).join('')}`),
    formatSection('E', `<div class="foundation-incident"><span class="section-kicker">ILLUSTRATIVE INCIDENT — NOT AN OBSERVED RESULT</span>${steps.map((s,i)=>`${header(`${i + 1}. ${s}`)}${p(x.incident[i])}`).join('')}</div>`),
    formatSection('F', `${list(x.takeaways)}<p><strong>Interview rule:</strong> State what you know, identify assumptions, give the simplest valid alternative, and name the evidence that would change your decision.</p>`)
  ];
}
